set -eu; for f in resolution-report.md restart-gate.json ledger-repair.json handoff-repair.json paperclip-adjudication.json changes.patch; do test -e "$f" || { echo "FAIL missing $f" >&2; exit 1; }; done; /usr/bin/python3 - <<'PY'
import json, pathlib
restart=json.load(open('restart-gate.json'))
ledger=json.load(open('ledger-repair.json'))
handoff=json.load(open('handoff-repair.json'))
paperclip=json.load(open('paperclip-adjudication.json'))
if restart.get('verdict') not in {'HOLD','GO'}: raise SystemExit('FAIL invalid restart verdict')
if restart.get('verdict') == 'GO' and (restart.get('ringside_active') or restart.get('paperclip_live_runs') or restart.get('recent_heartbeats') or restart.get('blockers')): raise SystemExit('FAIL unsafe GO')
if ledger.get('publication_performed') is not False: raise SystemExit('FAIL production publication occurred')
if 'current_pointer_before' not in ledger or 'current_pointer_after' not in ledger or ledger.get('current_pointer_before') != ledger.get('current_pointer_after'): raise SystemExit('FAIL ledger pointer changed or missing')
if 'pointer_before' not in handoff or 'pointer_after' not in handoff or handoff.get('pointer_before') != handoff.get('pointer_after'): raise SystemExit('FAIL handoff pointer changed or missing')
agents=paperclip.get('agents')
required={'Operator','Coder','Analyst-Opus','Fable','Pi Campaign Auditor','Analyst-Sonnet'}
if not isinstance(agents,dict) or not required.issubset(set(agents)): raise SystemExit('FAIL missing agent adjudications: '+repr(required-(set(agents) if isinstance(agents,dict) else set())))
report=pathlib.Path('resolution-report.md').read_text()
for term in ['completed','prepared-not-deployed','blocked','human-gated','rollback','definition of done']:
    if term.lower() not in report.lower(): raise SystemExit('FAIL report missing '+term)
print('EXECUTED_CHECK=PASS bounded resolution artifacts and no-publication invariants verified')
PY
